import * as M from './model.mjs';
import {bindTouchTaskDrag} from './touch-drag.mjs';
const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const symbols={pending:'□',partial:'△',done:'✓'}, names={today:'Today',inbox:'Inbox',all:'전체보기',upcoming:'예정',category:'카테고리',history:'기록 달력',diary:'일기'};
let state=M.emptyState(),db,persistedRevision=0,queue=Promise.resolve(),saveError='',lastFocus=null,drag=null,journalTimer,toastTimer;
const ui={view:'today',date:M.today(),month:M.today().slice(0,7),mode:'plan',listView:'today',group:false,category:'muniv',status:'all',selected:null,sourceDate:M.today(),sourceKind:'ACTUAL',selectedRecords:new Set()};
function btn(label,action,props='',cls=''){return `<button type="button" class="${cls}" data-action="${action}" ${props}>${label}</button>`;}
function icon(name,action,label){return `<button class="icon" data-action="${action}" aria-label="${label}" title="${label}"><img src="assets/${name}.svg" alt="" width="24" height="24"></button>`;}
function tabs(options,value,action){return `<div class="tabs" role="tablist">${options.map(([v,l])=>`<button type="button" role="tab" aria-selected="${v===value}" class="tab ${v===value?'active':''}" data-action="${action}" data-value="${v}">${l}</button>`).join('')}</div>`;}
function fmt(date){return new Intl.DateTimeFormat('ko-KR',{month:'long',day:'numeric',weekday:'short',timeZone:'Asia/Seoul'}).format(new Date(date+'T12:00:00Z'));}
function clock(n){return `${String(Math.floor(n/60)).padStart(2,'0')}:${String(n%60).padStart(2,'0')}`;}
function minutes(value){if(value==='24:00')return 1440;const [h,m]=value.split(':').map(Number);return h*60+m;}
function relative(date){return !date?'날짜 없음':date===M.today()?'오늘':date===M.shift(M.today())?'내일':fmt(date);}
function stat(date){const c=M.counts(state,date);return `<div class="review-counts" aria-label="완료 ${c.done}개, 일부 진행 ${c.partial}개, 미완료 ${c.pending}개"><span title="완료">✓ ${c.done}</span><span title="일부 진행">△ ${c.partial}</span><span title="미완료">□ ${c.pending}</span></div>`;}
function options(category){return `<option value="">지정하지 않음</option>${state.categories.map(c=>`<option value="${esc(c.id)}" ${c.id===category?'selected':''}>${esc(c.name)}</option>`).join('')}`;}
function field(label,content){return `<label class="field"><span>${label}</span>${content}</label>`;}
function quickForm(category='',date=''){return `<form class="quick-form" data-form="inline-task" data-category="${esc(category)}" data-date="${date}"><span>+</span><input name="title" aria-label="할 일 제목" placeholder="할 일 입력…" autocomplete="off" maxlength="300"><span>Enter</span></form>`;}
function dailyTasks(date){const records=Object.values(state.days[date]?.tasks||{});const current=state.tasks.filter(t=>t.date===date);const map=new Map(records.map(t=>[t.id,t]));current.forEach(t=>{const previous=map.get(t.id);map.set(t.id,previous?.movedTo?{...t,movedTo:previous.movedTo}:t);});return M.ordered(state,[...map.values()]);}
function activeTasks(){const continued=new Set(state.tasks.filter(t=>t.continuationOf).map(t=>t.continuationOf));return state.tasks.filter(t=>{let current=t;while(current){if(continued.has(current.id))return false;current=state.tasks.find(x=>x.id===current.parentId);}return true;});}
function taskRows(tasks,{boxed=false,depth=0,showDate=true,dayDate=null}={}){
  if(!tasks.length)return '<div class="empty">아직 할 일이 없습니다.<br>생각난 일을 하나 적어보세요.</div>';
  const ids=new Set(tasks.map(t=>t.id));const render=(t,d)=>{const kids=tasks.filter(c=>c.parentId===t.id);const cat=t.categoryName||M.categoryName(state,t.category);const meta=[cat,showDate?relative(t.date):'',t.continuationOf?`${fmt(t.sourceDate)}에서 이어짐`:'',t.movedTo?`${relative(t.movedTo)}로 미룸`:'',t.appointment?'고정 약속':'',kids.length?`하위 작업 ${kids.length}개`:''].filter(Boolean).join(' · ');
  const row=`<div class="task-row ${boxed?'boxed':''} ${t.status==='done'?'done':''} ${ui.selected===t.id?'selected':''}" data-task="${esc(t.id)}" data-log-date="${dayDate||t.date||''}" draggable="true" tabindex="0" style="margin-left:${d*24}px"><button class="handle" title="끌어서 순서 변경 또는 시간표 배치" aria-label="${esc(t.title)} 끌기" type="button">⠿</button>${kids.length?btn(t.collapsed?'▸':'▾','collapse',`data-id="${t.id}" aria-label="하위 작업 ${t.collapsed?'펼치기':'접기'}"`,'toggle'):''}${btn(symbols[t.status]||'□','status',`data-id="${t.id}" data-date="${dayDate||t.date||''}" title="미완료 → 일부 진행 → 완료" aria-label="${esc(t.title)} 상태 변경"`,'status')}<div class="grow">${btn(esc(t.title)+(t.appointment?' ◷':''),'edit-task',`data-id="${t.id}"`,'task-title')}<small>${esc(meta)}</small></div>${btn('⋯','task-menu',`data-id="${t.id}" aria-label="${esc(t.title)} 메뉴"`,'more')}</div>`;return row+(!t.collapsed?kids.map(c=>render(c,d+1)).join(''):'');};
  return `<div class="task-list">${tasks.filter(t=>!t.parentId||!ids.has(t.parentId)).map(t=>render(t,depth)).join('')}</div>`;
}
function sidebar(){return `<aside class="sidebar"><h2>TODO</h2><p class="caption">나의 하루</p><nav class="nav" aria-label="주요 메뉴">${Object.entries(names).map(([v,l])=>btn(v==='today'?'오늘':l,'nav',`data-value="${v}"`,ui.view===v?'active':'')).join('')}</nav><hr style="border:0;border-top:1px solid var(--border);width:100%"><strong class="caption">카테고리</strong><div class="category-nav">${state.categories.map(c=>btn('● '+esc(c.name),'select-category',`data-id="${c.id}"`,'subtle')).join('')}</div><div class="sidebar-footer"><span class="save-state">${saveError?'저장 실패': '이 브라우저에 저장됨'}</span>${btn('백업 · 복원','backup','','subtle')}${btn('사용 안내','help','','subtle')}</div></aside>`;}
function render(){
 const title=ui.view==='today'?(ui.date===M.today()?'Today':relative(ui.date)):names[ui.view];
 const scroll=$('.timeline-scroll')?.scrollTop;
 $('#app').innerHTML=`<header class="topbar"><h1>${esc(title)}</h1><div class="datebar">${btn('‹','prev-date','aria-label="이전 날짜"')}${btn(esc(fmt(ui.date))+' ▾','date-picker')}${btn('›','next-date','aria-label="다음 날짜"')}</div><div class="top-actions">${btn('+ 할 일','quick-add','','primary')}${icon('help','help','단축키 도움말')}</div></header><div class="layout">${sidebar()}<main class="main">${saveError?`<div class="error-banner">${esc(saveError)} ${btn('기록 백업','export')}</div>`:''}${({today:renderToday,inbox:renderInbox,all:renderAll,category:renderCategory,upcoming:renderUpcoming,history:renderHistory,diary:renderDiary}[ui.view])()}</main></div>`;
 bindTimeline();const timeline=$('.timeline-scroll');if(timeline)timeline.scrollTop=scroll??(8*60);
}
function renderToday(){let list=ui.listView==='today'?dailyTasks(ui.date):M.ordered(state,activeTasks());if(ui.listView==='category')list=list.filter(t=>t.category===ui.category);
 return `<div class="today-layout"><section class="task-panel"><h2>${relative(ui.date)} 할 일</h2>${tabs([['today',relative(ui.date)],['all','전체'],['category','카테고리']],ui.listView,'list-view')}${ui.listView==='category'?`<select data-control="list-category" aria-label="카테고리 선택">${options(ui.category)}</select>`:''}${quickForm('',ui.date)}${taskRows(list,{dayDate:ui.listView==='today'?ui.date:null})}<div class="row end">${btn('전체 내일로 미루기','postpone')}</div><section class="review"><h3>하루 회고</h3>${stat(ui.date)}<div class="row end">${btn('일기 쓰기','open-diary','','primary')}</div></section></section>${timeline()}</div>`;
}
function timeline(){const d=state.days[ui.date]||{plan:[],actual:[]};const blocks=d[ui.mode];const tasks=dailyTasks(ui.date).filter(t=>!t.parentId&&!blocks.some(b=>b.taskId===t.id));return `<section class="timeline"><div class="row">${tabs([['plan','PLAN'],['actual','ACTUAL']],ui.mode,'timeline-mode')}<div class="grow"></div>${ui.mode==='actual'?icon('actual','add-actual','실제 기록 추가'):icon('calendar','date-picker','날짜 선택')}</div><div class="lane drop-target" data-zone="all-day"><strong>종일</strong><div class="lane-tasks">${blocks.filter(b=>b.allDay).map(b=>btn(esc(b.title),'edit-block',`data-id="${b.id}"`,'chip')).join('')||'<span class="caption">종일 일정 없음</span>'}</div></div><div class="lane drop-target" data-zone="untimed"><strong>시간 미지정</strong><div class="lane-tasks">${tasks.map(t=>`<button class="chip" draggable="true" data-task="${t.id}" data-action="edit-task" data-id="${t.id}">${symbols[t.status]} ${esc(t.title)}</button>`).join('')||'<span class="caption">시간이 비어 있는 할 일 없음</span>'}</div></div><div class="timeline-scroll"><div class="time-axis" data-zone="timeline" aria-label="${ui.mode==='plan'?'계획':'실제 기록'} 시간표">${Array.from({length:24},(_,h)=>`<div class="hour" style="top:${h*60}px"><span>${String(h).padStart(2,'0')}:00</span></div>`).join('')}${placeBlocks(blocks.filter(b=>!b.allDay))}</div></div><p class="caption" style="margin-top:12px">${ui.mode==='plan'?'할 일을 끌어 배치하세요. 빈 칸을 더블클릭해도 됩니다.':'빈 칸을 눌러 끌면 실제 기록을 그릴 수 있습니다.'} · 블록 더블클릭: 수정<br>모바일: 할 일 옆 ⠿ 손잡이를 터치해 시간표로 끌어 놓으세요.</p></section>`;}
function placeBlocks(blocks){
 const sorted=[...blocks].sort((a,b)=>a.start-b.start);let groups=[],group=[],end=-1;for(const b of sorted){if(b.start>=end&&group.length){groups.push(group);group=[];end=-1;}group.push(b);end=Math.max(end,b.end);}if(group.length)groups.push(group);
 return groups.map(g=>{const cols=[];const positions=new Map();for(const b of g){let c=cols.findIndex(end=>end<=b.start);if(c<0)c=cols.length;cols[c]=b.end;positions.set(b.id,c);}return g.map(b=>{const c=positions.get(b.id),width=100/cols.length;return `<div class="schedule ${ui.mode}" data-block="${b.id}" tabindex="0" title="${esc(b.title)} · ${clock(b.start)}–${clock(b.end)}" style="top:${b.start}px;height:${b.end-b.start}px;left:calc(72px + (100% - 82px) * ${c/cols.length});width:calc((100% - 82px) * ${1/cols.length});right:auto"><strong>${esc(b.title)}${b.appointment?' ◷':''}</strong><small>${esc(b.categoryName)} · ${clock(b.start)}–${clock(b.end)}</small><div class="resize" data-resize="${b.id}" aria-label="길이 조절"></div></div>`;}).join('');}).join('');
}
function detailForm(t){return `<form data-form="task" data-id="${t.id}" class="stack">${field('제목',`<input name="title" value="${esc(t.title)}" maxlength="300" required>`)}${field('카테고리',`<select name="category">${options(t.category)}</select>`)}${field('날짜',`<input type="date" name="date" value="${t.date||''}">`)}<div class="row">${btn('오늘','set-form-date',`data-value="${M.today()}"`)}${btn('내일','set-form-date',`data-value="${M.shift(M.today())}"`)}${btn('날짜 없음','set-form-date','data-value=""')}</div><label class="check"><input type="checkbox" name="appointment" ${t.appointment?'checked':''}>고정 약속으로 표시</label>${field('메모',`<textarea name="note">${esc(t.note||'')}</textarea>`)}<div class="row end">${btn('저장','submit-form','','primary')}</div></form>`;}
function renderInbox(){const list=M.ordered(state,activeTasks().filter(t=>!t.category));const selected=state.tasks.find(t=>t.id===ui.selected&&list.some(x=>x.id===t.id));return `<div class="screen-stack"><h2>정리할 할 일 ${list.filter(t=>!t.parentId).length}</h2><p class="caption">제목만 적고, 날짜와 카테고리는 나중에 정합니다.</p><div class="inbox-layout"><section class="surface stack">${quickForm()}${taskRows(list,{boxed:true})}</section><aside class="detail stack"><h2>할 일 정리</h2>${selected?detailForm(selected):'<p class="caption">목록의 할 일을 누르면 여기에서 정리할 수 있습니다.</p>'}</aside></div><p class="caption">카테고리를 지정하면 Inbox에서 정리됩니다. 날짜만 정한 항목은 분류할 때까지 Inbox에도 남습니다.</p></div>`;}
function renderAll(){const tasks=M.ordered(state,activeTasks().filter(t=>ui.status==='all'||(ui.status==='done'?t.status==='done':t.status!=='done')));return `<div class="screen-stack"><div class="toolbar">${tabs([['list','목록'],['group','카테고리별']],ui.group?'group':'list','group')}<span class="spacer"></span><select data-control="order" aria-label="정렬 방식" style="width:auto"><option value="created" ${!state.manualOrder?'selected':''}>입력 순서</option><option value="manual" ${state.manualOrder?'selected':''}>직접 정한 순서</option></select><select data-control="filter" aria-label="상태 필터" style="width:auto"><option value="all" ${ui.status==='all'?'selected':''}>모든 상태</option><option value="active" ${ui.status==='active'?'selected':''}>진행 중</option><option value="done" ${ui.status==='done'?'selected':''}>완료</option></select></div><div class="surface row between"><span>${state.manualOrder?'직접 정한 순서로 고정됨':'입력 순서 · 먼저 입력한 항목부터'}</span><span class="caption">손잡이를 끌어 순서를 바꾸면 자동으로 고정됩니다.</span></div>${quickForm()}${ui.group?`<div class="group-grid">${[...state.categories,{id:null,name:'Inbox'}].map(c=>`<section class="surface stack"><h3>${c.id?'● ':''}${esc(c.name)}</h3>${taskRows(tasks.filter(t=>t.category===c.id),{boxed:true})}</section>`).join('')}</div>`:`<section class="surface">${taskRows(tasks,{boxed:true})}</section>`}</div>`;}
function renderCategory(){const selected=state.categories.find(c=>c.id===ui.category)||state.categories[0];if(!selected)return `<div class="empty">카테고리가 없습니다. ${btn('+ 카테고리','manage-categories')}</div>`;ui.category=selected.id;const list=M.ordered(state,activeTasks().filter(t=>t.category===selected.id));return `<div class="category-layout"><section class="surface category-selector"><h2>카테고리</h2>${state.categories.map(c=>btn('● '+esc(c.name),'select-category',`data-id="${c.id}"`,ui.category===c.id?'active':'subtle')).join('')}${btn('+ 카테고리','manage-categories')}${btn('카테고리 관리','manage-categories','','subtle')}</section><section class="screen-stack"><div class="row between"><h2>● ${esc(selected.name)}</h2>${btn('⋯','manage-categories','','subtle')}</div><section class="surface">${taskRows(list,{boxed:true})}${quickForm(selected.id)}</section></section></div>`;}
function renderUpcoming(){const future=M.ordered(state,activeTasks().filter(t=>t.date&&t.date>M.today()));const dates=[...new Set(future.map(t=>t.date))].sort();if(!dates.length)dates.push(M.shift(M.today()));return `<div class="screen-stack"><h2>앞으로의 할 일</h2><p class="caption">날짜를 정한 할 일을 모아 봅니다. 다른 날짜 칸으로 끌어 옮길 수 있습니다.</p><div class="upcoming-grid">${dates.map(date=>`<section class="surface stack date-column drop-target" data-zone="date" data-date="${date}"><h3>${esc(fmt(date))}${date===M.shift(M.today())?' · 내일':''}</h3>${taskRows(future.filter(t=>t.date===date),{boxed:true})}${btn('이 날짜 계획하기','open-day',`data-date="${date}"`,'subtle')}</section>`).join('')}</div><div class="surface row between"><p class="caption">다른 날짜로 옮기려면 항목을 눌러 날짜를 수정할 수도 있습니다.</p>${btn('날짜 추가','upcoming-date')}</div></div>`;}
function calendar(month,selected,action,mini=false){const [y,m]=month.split('-').map(Number),first=new Date(Date.UTC(y,m-1,1,12));const start=M.shift(month+'-01',-((first.getUTCDay()+6)%7));return `<div class="${mini?'mini':''}"><div class="row between" style="margin-bottom:12px">${btn('‹','calendar-month',`data-value="-1" data-target="${action}"`,'subtle')}<h3>${y}년 ${m}월</h3>${btn('›','calendar-month',`data-value="1" data-target="${action}"`,'subtle')}</div><div class="calendar-grid">${['월','화','수','목','금','토','일'].map(x=>`<div class="weekday">${x}</div>`).join('')}${Array.from({length:42},(_,i)=>{const date=M.shift(start,i),c=M.counts(state,date),d=state.days[date],has=c.done+c.partial+c.pending;return `<button class="calendar-day ${date===selected?'active':''} ${date.slice(0,7)!==month?'off':''}" data-action="${action}" data-date="${date}" aria-label="${fmt(date)}"><span>${Number(date.slice(-2))}</span>${!mini&&has?`<span class="caption">✓${c.done} △${c.partial} □${c.pending}</span>`:''}${!mini&&d?.journal.some(b=>b.type!=='text'||b.text.trim())?'<span class="caption">▤ 일기</span>':''}${!mini&&!has&&d?.plan.length?'<span class="caption">계획 있음</span>':''}</button>`;}).join('')}</div></div>`;}
function renderHistory(){return `<div class="calendar-layout"><section class="surface stack">${calendar(ui.month,ui.date,'history-date')}<p class="caption">✓ 완료 · △ 일부 진행 · □ 미완료 · 상위 할 일 기준</p></section><aside class="detail stack"><h2>${esc(fmt(ui.date))}</h2>${stat(ui.date)}<h3>계획과 실제</h3><p>PLAN ${humanDuration(M.duration(state,ui.date,'plan'))} / ACTUAL ${humanDuration(M.duration(state,ui.date,'actual'))}</p><p class="caption">시간표에 기록된 시간 합계 · 종일 제외</p>${taskRows(dailyTasks(ui.date),{boxed:true,dayDate:ui.date})}${btn('이 날짜 시간표 보기','open-day',`data-date="${ui.date}"`,'primary')}${btn('일기 열기','open-diary')}<p class="caption">그날 마지막으로 정한 PLAN이 남습니다.<br>미루기와 ACTUAL 수정은 원래 PLAN을 바꾸지 않습니다.</p></aside></div>`;}
function humanDuration(n){return `${Math.floor(n/60)}시간${n%60?' '+n%60+'분':''}`;}
function sourceRecords(){const d=state.days[ui.sourceDate];if(!d)return [];return ui.sourceKind==='TODO'?Object.values(d.tasks):d[ui.sourceKind.toLowerCase()].map(b=>({...b,status:d.tasks[b.taskId]?.status||b.status}));}
function card(b){return `<div class="record-card"><small>${esc(b.kind)} · ${esc(b.date)}</small><strong>${esc(b.title)}</strong><small>${esc(b.categoryName)}${b.allDay?' · 종일':b.start!=null?' · '+clock(b.start)+'–'+clock(b.end):''} · ${symbols[b.status]||'□'}</small></div>`;}
function renderDiary(){const journal=state.days[ui.date]?.journal||[];return `<div class="journal-layout"><section class="journal-body stack"><div class="toolbar">${btn('+ 기록 삽입','focus-records')}<span class="spacer"></span>${icon('photo','photo','사진 첨부')}${btn('저장','save-journal','','primary')}</div><h2>${esc(fmt(ui.date))}의 기록</h2>${stat(ui.date)}<div class="journal-blocks">${journal.map((b,i)=>insertPoint(i)+`<section class="journal-block" data-journal-id="${b.id}"><div class="block-tools">${btn('↑','move-journal',`data-id="${b.id}" data-value="-1" ${i===0?'disabled':''}`)}${btn('↓','move-journal',`data-id="${b.id}" data-value="1" ${i===journal.length-1?'disabled':''}`)}${btn('삭제','remove-journal',`data-id="${b.id}"`)}</div>${b.type==='text'?`<textarea class="journal-editor" data-editor="${b.id}" aria-label="일기 본문" placeholder="오늘의 기록을 남겨보세요…">${esc(b.text)}</textarea>`:b.type==='card'?card(b):`<img class="photo" src="${esc(b.src)}" alt="일기에 첨부한 사진">`}</section>`).join('')}${insertPoint(journal.length)}</div><div class="row">${btn('+ 글 이어쓰기','add-paragraph','','subtle')}<span class="grow"></span><span class="caption" id="journal-save">자동 저장됨</span></div></section><aside class="surface stack record-panel" id="records"><h3>기록 가져오기</h3>${field('기록 날짜',`<input type="date" data-control="source-date" value="${ui.sourceDate}">`)}${tabs([['TODO','할 일'],['PLAN','PLAN'],['ACTUAL','ACTUAL']],ui.sourceKind,'source-kind')}${sourceRecords().map(r=>`<div class="record-source row" draggable="true" data-record="${r.id}"><input type="checkbox" data-control="select-record" data-id="${r.id}" ${ui.selectedRecords.has(r.id)?'checked':''} aria-label="${esc(r.title)} 선택"><div><strong>${symbols[r.status]||'□'} ${esc(r.title)}</strong><small>${r.start!=null?clock(r.start)+'–'+clock(r.end):relative(r.date)}</small></div></div>`).join('')||'<p class="caption">이 날짜의 기록이 없습니다.</p>'}${btn('선택한 기록 삽입','insert-records','','primary')}<p class="caption">원하는 본문 위치로 끌어놓을 수도 있습니다.<br>카드는 삽입 당시의 모습으로 유지됩니다.</p></aside></div>`;}
function insertPoint(i){return `<div class="insert-point" data-zone="journal" data-index="${i}">여기에 놓으면 기록 카드가 들어갑니다</div>`;}
function toast(s){clearTimeout(toastTimer);$('#toast').textContent=s;$('#toast').className='toast';toastTimer=setTimeout(()=>$('#toast').className='',3000);}
function openModal(title,body,width=480){lastFocus=document.activeElement;$('#modal').innerHTML=`<div class="modal-head"><h2>${title}</h2>${btn('×','close-modal','aria-label="닫기"','subtle')}</div><div class="modal-body">${body}</div>`;$('#modal').style.width=width+'px';if(!$('#modal').open)$('#modal').showModal();$('#modal').querySelector('input:not([type=checkbox]),textarea,select,button')?.focus();}
function quickTaskModal(forToday=false){openModal(forToday?'오늘 할 일 빠른 입력':'할 일 빠른 입력',`<form data-form="quick-task" data-target="${forToday?'today':'inbox'}">${field('제목','<input name="title" required placeholder="할 일 제목" maxlength="300" autocomplete="off">')}<p class="caption">${forToday?'제목만 입력하면 오늘 할 일에 추가됩니다.':'제목만 입력하면 Inbox에 들어갑니다.'}</p><div class="actions"><button class="primary" type="submit">추가</button></div></form>`,560);}
function closeModal(){if($('#modal').open)$('#modal').close();lastFocus?.focus();}
function act(fn,message='',rerender=true){const before=structuredClone(state);try{fn();if(rerender)render();persist();if(message)toast(message);return true;}catch(e){state=before;toast(e.message);return false;}}
function persist(){const payload=structuredClone(state);queue=queue.catch(()=>{}).then(()=>writeState(payload)).then(()=>{saveError='';if($('#journal-save'))$('#journal-save').textContent='자동 저장됨';}).catch(e=>{saveError=e.message==='conflict'?'다른 탭에서 기록이 바뀌었습니다. 이 탭의 내용을 백업한 뒤 새로고침해주세요.':'브라우저 저장에 실패했습니다. 현재 기록을 백업해주세요.';toast(saveError);if($('#journal-save'))$('#journal-save').textContent='저장 실패 · 백업해주세요';const indicator=$('.save-state');if(indicator)indicator.textContent='저장 실패';});return queue;}
function openDB(){return new Promise((resolve,reject)=>{const r=indexedDB.open('suhyun-todo',1);r.onupgradeneeded=()=>r.result.createObjectStore('data');r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);});}
function readState(){return new Promise((resolve,reject)=>{const tx=db.transaction('data','readonly'),r=tx.objectStore('data').get('state');r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);});}
function writeState(payload){return new Promise((resolve,reject)=>{const tx=db.transaction('data','readwrite'),store=tx.objectStore('data'),r=store.get('state');let failure;r.onsuccess=()=>{if((r.result?._rev||0)!==persistedRevision){failure=Error('conflict');tx.abort();return;}payload._rev=persistedRevision+1;store.put(payload,'state');};tx.oncomplete=()=>{persistedRevision=payload._rev;state._rev=persistedRevision;resolve();};tx.onabort=()=>reject(failure||tx.error||Error('저장 실패'));tx.onerror=()=>reject(tx.error);});}
function taskModal(tid){const t=state.tasks.find(t=>t.id===tid);if(!t){toast('이 항목은 지난 기록입니다. 시간표와 일기에서 확인할 수 있습니다.');return;}if(ui.view==='inbox'){closeModal();ui.selected=tid;render();return;}openModal('할 일 수정',detailForm(t)+`<div class="row">${btn('+ 하위 작업','add-child',`data-id="${tid}"`)}${btn('삭제','delete-task',`data-id="${tid}"`,'subtle danger')}</div><p class="caption">상위 작업의 상태는 직접 정합니다. 회고 개수에는 상위 할 일만 포함됩니다.</p>`);}
function scheduleModal(mode=ui.mode,bid=null,start=600,end=660,taskId=''){const b=bid?state.days[ui.date]?.[mode].find(b=>b.id===bid):null;const selectedTask=taskId||b?.taskId||'';const form=`<form data-form="block" data-mode="${mode}" data-id="${bid||''}">${mode==='actual'?`<div class="row">${btn('직접 기록','noop','','subtle')}${btn('PLAN에서 가져오기','from-plan','','subtle')}</div>`:''}${field(mode==='actual'?'무엇을 했나요?':'제목',`<input name="title" value="${esc(b?.title||state.tasks.find(t=>t.id===selectedTask)?.title||'')}" required maxlength="300" placeholder="${mode==='actual'?'실제로 한 일을 적어주세요':'계획 제목'}">`)}${field('연결할 할 일',`<select name="taskId"><option value="">${mode==='actual'?'없음 · 일상 기록':'연결하지 않음'}</option>${state.tasks.filter(t=>!t.parentId).map(t=>`<option value="${t.id}" ${selectedTask===t.id?'selected':''}>${esc(t.title)}</option>`).join('')}</select>`)}<div class="times">${field('시작',`<input type="time" name="start" value="${clock(b?.start??start)}" required step="300">`)}${field('끝',`<input type="time" name="end" value="${clock((b?.end??end)===1440?0:(b?.end??end))}" required step="300">`)}</div><label class="check"><input name="allDay" type="checkbox" ${b?.allDay?'checked':''}>종일</label><label class="check"><input name="appointment" type="checkbox" ${b?.appointment?'checked':''}>고정 약속</label><p class="caption">${mode==='actual'?'ACTUAL을 수정해도 PLAN은 그대로 남습니다.':'그날 마지막으로 정한 계획이 기록에 남습니다.'}</p><div class="actions">${bid?btn('삭제','delete-block',`data-id="${bid}" data-mode="${mode}"`,'subtle danger'):''}<button class="primary" type="submit">저장</button></div></form>`;openModal(mode==='actual'?'실제 한 일 기록':'계획 수정',form);}
function startDiary(){ui.view='diary';ui.selectedRecords.clear();if(!state.days[ui.date]?.journal.length){act(()=>M.day(state,ui.date).journal.push({id:M.id(),type:'text',text:''}),'',false);}render();}
function sourceSnapshot(r){return M.embed(state,ui.sourceDate,ui.sourceKind,r);}
function insertRecords(rs,index=null){if(!rs.length){toast('삽입할 기록을 선택해주세요.');return;}act(()=>{const blocks=M.day(state,ui.date).journal;blocks.splice(index??blocks.length,0,...rs.map(sourceSnapshot));ui.selectedRecords.clear();},'기록을 삽입했습니다.');}
function exportBackup(){const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`todo-backup-${M.today()}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('백업 파일을 다운로드했습니다.');}
function changeDate(date){if(!date)return;ui.date=date;ui.month=date.slice(0,7);ui.selected=null;render();}
document.addEventListener('click',async e=>{const button=e.target.closest('[data-action]');if(!button||button.disabled)return;const a=button.dataset.action,tid=button.dataset.id,value=button.dataset.value;try{switch(a){
 case 'nav':ui.view=value;if(value==='today'){ui.date=M.today();ui.month=ui.date.slice(0,7);}if(value==='diary')startDiary();else render();break;
 case 'select-category':ui.category=tid;ui.view='category';render();break;
 case 'prev-date':changeDate(M.shift(ui.date,-1));break;case 'next-date':changeDate(M.shift(ui.date));break;
 case 'date-picker':ui.pickerMonth=ui.date.slice(0,7);openModal('날짜 선택',calendar(ui.pickerMonth,ui.date,'pick-date',true)+field('날짜 직접 선택',`<input type="date" data-control="pick-date" value="${ui.date}">`),360);break;
 case 'pick-date':changeDate(button.dataset.date);closeModal();break;
 case 'history-date':changeDate(button.dataset.date);break;
 case 'calendar-month':{const target=button.dataset.target,key=target==='pick-date'?'pickerMonth':'month';const [y,m]=ui[key].split('-').map(Number);ui[key]=new Date(Date.UTC(y,m-1+Number(value),1,12)).toISOString().slice(0,7);if(target==='pick-date')openModal('날짜 선택',calendar(ui[key],ui.date,'pick-date',true),360);else render();break;}
 case 'open-day':ui.view='today';changeDate(button.dataset.date);break;
 case 'quick-add':quickTaskModal();break;
 case 'edit-task':taskModal(tid);break;
 case 'submit-form':button.closest('form').requestSubmit();break;
 case 'set-form-date':button.closest('form').elements.date.value=value;break;
 case 'close-modal':closeModal();break;
 case 'collapse':act(()=>{const t=state.tasks.find(t=>t.id===tid);if(t){t.collapsed=!t.collapsed;M.logTask(state,t);}});break;
 case 'status':{const date=button.dataset.date||ui.date,t=dailyTasks(date).find(t=>t.id===tid)||state.tasks.find(t=>t.id===tid);if(!t)break;if(!t.date&&!button.dataset.date){act(()=>{M.editTask(state,tid,{date:ui.date});M.changeStatus(state,tid,ui.date,{pending:'partial',partial:'done',done:'pending'}[t.status]);});}else act(()=>M.changeStatus(state,tid,date,{pending:'partial',partial:'done',done:'pending'}[t.status]),t.status==='pending'?'△ 기록 · 다음 날 이어 할 일이 생겼습니다.':'상태를 바꿨습니다.');break;}
 case 'task-menu':openModal('할 일 메뉴',`<div class="stack">${btn('수정','edit-task',`data-id="${tid}"`,'subtle')}${btn('◷ 약속 표시 전환','toggle-appointment',`data-id="${tid}"`,'subtle')}${btn('+ 하위 작업 추가','add-child',`data-id="${tid}"`,'subtle')}${btn('삭제','delete-task',`data-id="${tid}"`,'subtle danger')}</div>`,300);break;
 case 'toggle-appointment':act(()=>{const t=state.tasks.find(t=>t.id===tid);if(t)M.editTask(state,tid,{appointment:!t.appointment});});closeModal();break;
 case 'add-child':{const parent=state.tasks.find(t=>t.id===tid);if(!parent)break;openModal('하위 작업 추가',`<form data-form="child" data-id="${tid}">${field('제목','<input name="title" required maxlength="300" placeholder="작은 행동으로 나눠보세요">')}<div class="actions"><button type="submit" class="primary">추가</button></div></form>`);break;}
 case 'delete-task':openModal('할 일 삭제',`<p>하위 작업도 함께 삭제됩니다. 시간표와 일기 카드의 기록은 남습니다.</p><div class="actions">${btn('취소','close-modal')}${btn('삭제','confirm-delete-task',`data-id="${tid}"`,'danger')}</div>`);break;
 case 'confirm-delete-task':act(()=>M.removeTask(state,tid),'할 일을 삭제했습니다.');closeModal();break;
 case 'list-view':ui.listView=value;render();break;case 'group':ui.group=value==='group';render();break;
 case 'timeline-mode':ui.mode=value;render();break;
 case 'edit-block':scheduleModal(ui.mode,tid);break;case 'add-actual':scheduleModal('actual');break;
 case 'delete-block':act(()=>{const arr=M.day(state,ui.date)[button.dataset.mode];arr.splice(arr.findIndex(b=>b.id===tid),1);},'기록을 삭제했습니다.');closeModal();break;
 case 'from-plan':openModal('PLAN에서 실제 기록 가져오기',`<form data-form="from-plan">${field('계획',`<select name="blockId" required>${(state.days[ui.date]?.plan||[]).map(b=>`<option value="${b.id}">${esc(b.title)} · ${b.allDay?'종일':clock(b.start)+'–'+clock(b.end)}</option>`).join('')}</select>`)}<div class="times">${field('실제 시작','<input type="time" name="start" value="10:00" required>')}${field('실제 끝','<input type="time" name="end" value="11:00" required>')}</div><p class="caption">실제 시간을 바꿔 기록합니다. 원래 PLAN은 유지됩니다.</p><div class="actions"><button type="submit" class="primary">ACTUAL에 추가</button></div></form>`);break;
 case 'postpone':{const pending=state.tasks.filter(t=>!t.parentId&&t.date===ui.date&&t.status!=='done');openModal('전체 내일로 미루기',`<p>남은 할 일을 ${esc(fmt(M.shift(ui.date)))}로 옮깁니다.</p><div class="surface stack">${pending.map(t=>`<p>${symbols[t.status]} ${esc(t.title)}${t.appointment?' ◷':''}</p>`).join('')||'<p>옮길 할 일이 없습니다.</p>'}</div><label class="check"><input id="include-appointments" type="checkbox">고정 약속도 포함</label><p class="caption">△로 생긴 이어 할 일은 중복 생성하지 않습니다.<br>새 날짜의 시간은 비워두고 원래 PLAN을 보존합니다.</p><div class="actions">${btn('취소','close-modal')}${btn('내일로 옮기기','confirm-postpone','','primary')}</div>`);break;}
 case 'confirm-postpone':{const include=$('#include-appointments').checked;act(()=>{const n=M.postpone(state,ui.date,include);toast(`${n}개를 내일로 옮겼습니다.`);});closeModal();break;}
 case 'manage-categories':categoryModal();break;
 case 'rename-category':{const c=state.categories.find(c=>c.id===tid);openModal('카테고리 이름 변경',`<form data-form="rename-category" data-id="${tid}">${field('이름',`<input name="name" value="${esc(c.name)}" required maxlength="40">`)}<button class="primary" type="submit">저장</button></form>`);break;}
 case 'delete-category':openModal('카테고리 삭제',`<p>해당 할 일은 Inbox로 이동합니다. 지난 시간표와 일기의 카테고리 이름은 보존합니다.</p><div class="actions">${btn('취소','close-modal')}${btn('삭제','confirm-delete-category',`data-id="${tid}"`,'danger')}</div>`);break;
 case 'confirm-delete-category':act(()=>{state.categories=state.categories.filter(c=>c.id!==tid);for(const t of state.tasks.filter(t=>t.category===tid))M.editTask(state,t.id,{category:null});ui.category=state.categories[0]?.id||null;});closeModal();break;
 case 'upcoming-date':openModal('계획할 날짜',`<form data-form="open-day">${field('날짜',`<input type="date" name="date" value="${M.shift(M.today())}" required>`)}<button class="primary" type="submit">이 날짜 열기</button></form>`,360);break;
 case 'open-diary':startDiary();break;
 case 'source-kind':ui.sourceKind=value;ui.selectedRecords.clear();render();break;
 case 'focus-records':$('#records')?.scrollIntoView({behavior:'smooth',block:'center'});$('#records input')?.focus();break;
 case 'insert-records':insertRecords(sourceRecords().filter(r=>ui.selectedRecords.has(r.id)));break;
 case 'add-paragraph':act(()=>M.day(state,ui.date).journal.push({id:M.id(),type:'text',text:''}));$('.journal-blocks')?.lastElementChild?.previousElementSibling?.querySelector('textarea')?.focus();break;
 case 'remove-journal':act(()=>{const blocks=M.day(state,ui.date).journal;blocks.splice(blocks.findIndex(b=>b.id===tid),1);});break;
 case 'move-journal':act(()=>{const blocks=M.day(state,ui.date).journal,i=blocks.findIndex(b=>b.id===tid),n=i+Number(value);if(n>=0&&n<blocks.length){const [b]=blocks.splice(i,1);blocks.splice(n,0,b);}});break;
 case 'save-journal':clearTimeout(journalTimer);await persist();if(!saveError)toast('일기를 저장했습니다.');break;
 case 'photo':choosePhotos();break;
 case 'backup':openModal('백업 · 복원',`<p>기록은 이 노트북의 현재 브라우저에 저장됩니다.</p><p class="caption">다른 브라우저로 옮기거나 브라우저 데이터를 지우기 전에는 백업 파일을 내려받아 주세요.</p><div class="backup-box">${btn('백업 다운로드','export','','primary')}${btn('백업 복원','import')}</div><p class="caption">복원하면 현재 기록을 백업 파일의 내용으로 바꿉니다.</p>`);break;
 case 'export':exportBackup();break;case 'import':importBackup();break;
 case 'help':openModal('단축키와 사용 안내',`<div class="shortcut"><kbd>/</kbd><p>오늘 할 일 빠른 입력 열기</p></div><div class="shortcut"><kbd>Enter</kbd><p>입력한 할 일 추가</p></div><div class="shortcut"><kbd>Tab</kbd><p>할 일 행 선택 중 들여쓰기</p></div><div class="shortcut"><kbd>Shift + Tab</kbd><p>할 일 행 선택 중 내어쓰기</p></div><div class="shortcut"><kbd>Esc</kbd><p>창 닫기</p></div><p class="caption">할 일을 우클릭하면 약속 표시와 하위 작업 메뉴가 열립니다.<br>상태 아이콘은 □ → △ → ✓ 순서로 바뀝니다.<br>사진·글·카드도 같은 브라우저에 저장됩니다.</p>`,520);break;
 }}catch(error){toast(error.message);}});
document.addEventListener('submit',e=>{const form=e.target;if(!form.dataset.form)return;e.preventDefault();const f=new FormData(form),kind=form.dataset.form;try{switch(kind){
 case 'inline-task':case 'quick-task':{let created;if(act(()=>{created=M.addTask(state,f.get('title'),kind==='inline-task'?{category:form.dataset.category||null,date:form.dataset.date||null}:form.dataset.target==='today'?{date:M.today()}:{});},'할 일을 추가했습니다.')){if(kind==='quick-task')closeModal();else document.querySelector(`[data-task="${created.id}"]`)?.focus();}break;}
 case 'task':if(act(()=>M.editTask(state,form.dataset.id,{title:f.get('title').trim(),category:f.get('category')||null,date:f.get('date')||null,note:f.get('note'),appointment:f.has('appointment')}),'저장했습니다.'))closeModal();break;
 case 'child':act(()=>{const t=state.tasks.find(t=>t.id===form.dataset.id);t.collapsed=false;M.addTask(state,f.get('title'),{parentId:t.id,category:t.category,date:t.date});},'하위 작업을 추가했습니다.');closeModal();break;
 case 'block':{const props={title:f.get('title').trim(),taskId:f.get('taskId')||null,start:minutes(f.get('start')),end:minutes(f.get('end')),allDay:f.has('allDay'),appointment:f.has('appointment')};if(props.end===0&&props.start>0)props.end=1440;const related=state.tasks.find(t=>t.id===props.taskId);props.categoryName=related?M.categoryName(state,related.category):'일상';if(props.allDay){props.start=0;props.end=1440;}const ok=act(()=>{if(form.dataset.id)M.updateBlock(state,ui.date,form.dataset.mode,form.dataset.id,props);else M.addBlock(state,ui.date,form.dataset.mode,props);},'기록했습니다.');if(ok)closeModal();break;}
 case 'from-plan':{const start=minutes(f.get('start')),raw=minutes(f.get('end')),end=raw===0&&start>0?1440:raw;if(act(()=>M.actualFromPlan(state,ui.date,f.get('blockId'),start,end),'ACTUAL에 기록했습니다.')){closeModal();ui.mode='actual';render();}break;}
 case 'new-category':act(()=>{const name=f.get('name').trim();if(!name)throw Error('이름을 입력해주세요.');if(state.categories.some(c=>c.name===name))throw Error('이미 있는 이름입니다.');state.categories.push({id:M.id(),name});});categoryModal();break;
 case 'rename-category':act(()=>{state.categories.find(c=>c.id===form.dataset.id).name=f.get('name').trim();});closeModal();break;
 case 'open-day':ui.view='today';changeDate(f.get('date'));closeModal();break;
 }}catch(error){toast(error.message);}});
document.addEventListener('change',e=>{const c=e.target.dataset.control;if(!c)return;switch(c){case 'order':act(()=>state.manualOrder=e.target.value==='manual');break;case 'filter':ui.status=e.target.value;render();break;case 'list-category':ui.category=e.target.value;render();break;case 'source-date':ui.sourceDate=e.target.value;ui.selectedRecords.clear();render();break;case 'select-record':e.target.checked?ui.selectedRecords.add(e.target.dataset.id):ui.selectedRecords.delete(e.target.dataset.id);break;case 'pick-date':changeDate(e.target.value);closeModal();break;}});
document.addEventListener('input',e=>{if(!e.target.dataset.editor)return;const b=M.day(state,ui.date).journal.find(b=>b.id===e.target.dataset.editor);if(b){b.text=e.target.value;if($('#journal-save'))$('#journal-save').textContent='저장 중…';clearTimeout(journalTimer);journalTimer=setTimeout(()=>persist(),350);}});
document.addEventListener('keydown',e=>{if(e.isComposing)return;const editing=e.target.matches('input,textarea,select,[contenteditable=true]');if(e.key==='/'&&!editing&&!$('#modal').open){e.preventDefault();quickTaskModal(true);}if(e.key==='Tab'&&!editing&&!$('#modal').open){const row=e.target.closest('.task-row');if(row&&state.tasks.some(t=>t.id===row.dataset.task)){e.preventDefault();const tid=row.dataset.task;act(()=>M.indent(state,tid,e.shiftKey));document.querySelector(`[data-task="${tid}"]`)?.focus();}}if(e.key==='Enter'&&e.target.matches('.schedule')){scheduleModal(ui.mode,e.target.dataset.block);} });
document.addEventListener('contextmenu',e=>{const row=e.target.closest('[data-task]');if(row){e.preventDefault();document.querySelector(`[data-action="task-menu"][data-id="${row.dataset.task}"]`)?.click();}});
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=$('#modal').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal();}});
function categoryModal(){openModal('카테고리 관리',`${state.categories.map(c=>`<div class="surface row"><span class="grow">● ${esc(c.name)}</span>${btn('이름 변경','rename-category',`data-id="${c.id}"`,'subtle')}${btn('×','delete-category',`data-id="${c.id}" aria-label="${esc(c.name)} 삭제"`,'subtle')}</div>`).join('')}<form data-form="new-category">${field('새 카테고리','<input name="name" required maxlength="40" placeholder="카테고리 이름">')}<div class="actions"><button class="primary" type="submit">추가</button></div></form>`);}
document.addEventListener('dragstart',e=>{const rec=e.target.closest('[data-record]'),task=e.target.closest('[data-task]');if(rec)drag={type:'record',id:rec.dataset.record};else if(task)drag={type:'task',id:task.dataset.task};if(drag){e.dataTransfer.setData('text/plain',JSON.stringify(drag));e.dataTransfer.effectAllowed='copyMove';}});
document.addEventListener('dragover',e=>{if(!drag)return;const zone=e.target.closest('[data-zone]'),row=e.target.closest('.task-row');if(zone||row){e.preventDefault();if(zone)zone.classList.add('over');if(zone?.dataset.zone==='timeline'){const n=Math.max(0,Math.min(1425,Math.round((e.clientY-zone.getBoundingClientRect().top)/15)*15));let mark=zone.querySelector('.drop-mark');if(!mark){mark=document.createElement('div');mark.className='drop-mark';zone.append(mark);}mark.style.top=n+'px';mark.innerHTML=`<span>${clock(n)}</span>`;}}});
document.addEventListener('dragleave',e=>{e.target.closest('[data-zone]')?.classList.remove('over');});
function previewTaskDrop(zone,y){if(zone?.dataset.zone!=='timeline')return;const n=Math.max(0,Math.min(1425,Math.round((y-zone.getBoundingClientRect().top)/15)*15));const mark=document.createElement('div');mark.className='drop-mark';mark.style.top=n+'px';mark.innerHTML=`<span>${clock(n)}</span>`;zone.append(mark);}
function dropTask(tid,zone,row,y){if(zone?.dataset.zone==='timeline'){const start=Math.max(0,Math.min(1380,Math.round((y-zone.getBoundingClientRect().top)/15)*15));act(()=>M.addBlock(state,ui.date,ui.mode,{taskId:tid,start,end:Math.min(start+60,1440)}),'시간표에 배치했습니다.');}else if(zone?.dataset.zone==='all-day'){act(()=>M.addBlock(state,ui.date,ui.mode,{taskId:tid,allDay:true,start:0,end:1440}));}else if(zone?.dataset.zone==='untimed'){act(()=>M.moveTask(state,tid,ui.date));}else if(zone?.dataset.zone==='date'){act(()=>M.moveTask(state,tid,zone.dataset.date));}else if(row&&row.dataset.task!==tid){act(()=>M.reorder(state,tid,row.dataset.task));}}
document.addEventListener('drop',e=>{if(!drag)return;e.preventDefault();const zone=e.target.closest('[data-zone]'),row=e.target.closest('.task-row'),data=drag;cleanupDrag();if(zone?.dataset.zone==='journal'&&data.type==='record'){const r=sourceRecords().find(r=>r.id===data.id);if(r)insertRecords([r],Number(zone.dataset.index));}else if(data.type==='task')dropTask(data.id,zone,row,e.clientY);});
bindTouchTaskDrag({resolveTask:tid=>state.tasks.find(t=>t.id===tid)?.title,onDrop:dropTask,onPreview:previewTaskDrop});
document.addEventListener('dragend',cleanupDrag);function cleanupDrag(){drag=null;document.querySelectorAll('.over').forEach(n=>n.classList.remove('over'));document.querySelectorAll('.drop-mark').forEach(n=>n.remove());}
function bindTimeline(){const axis=$('.time-axis');if(!axis)return;axis.addEventListener('dblclick',e=>{const block=e.target.closest('[data-block]');if(block){scheduleModal(ui.mode,block.dataset.block);return;}const start=Math.max(0,Math.min(1380,Math.round((e.clientY-axis.getBoundingClientRect().top)/15)*15));scheduleModal(ui.mode,null,start,start+60);});
 axis.addEventListener('pointerdown',e=>{if(e.button!==0||e.target.closest('button'))return;const el=e.target.closest('[data-block]');if(!el&&ui.mode!=='actual')return;e.preventDefault();const initialY=e.clientY;let changed=false,from=0,to=0,block=el?M.day(state,ui.date)[ui.mode].find(b=>b.id===el.dataset.block):null;const resize=!!e.target.closest('[data-resize]');const original=block?{start:block.start,end:block.end}:null;let marker;if(!block){from=Math.max(0,Math.min(1425,Math.round((e.clientY-axis.getBoundingClientRect().top)/15)*15));to=from+15;marker=document.createElement('div');marker.className='schedule moving';marker.style.top=from+'px';marker.style.height='15px';axis.append(marker);}el?.classList.add('moving');
 const move=ev=>{const delta=Math.round((ev.clientY-initialY)/15)*15;if(Math.abs(ev.clientY-initialY)>3)changed=true;if(block){if(resize){to=Math.max(original.start+15,Math.min(1440,original.end+delta));from=original.start;}else{const duration=original.end-original.start;from=Math.max(0,Math.min(1440-duration,original.start+delta));to=from+duration;}el.style.top=from+'px';el.style.height=to-from+'px';}else{to=Math.max(from+15,Math.min(1440,Math.round((ev.clientY-axis.getBoundingClientRect().top)/15)*15));marker.style.height=to-from+'px';}};
 const finish=()=>{document.removeEventListener('pointermove',move);document.removeEventListener('pointerup',finish);document.removeEventListener('pointercancel',cancel);el?.classList.remove('moving');marker?.remove();if(block&&changed)act(()=>M.updateBlock(state,ui.date,ui.mode,block.id,{start:from,end:to}));else if(!block)scheduleModal('actual',null,from,to);};
 const cancel=()=>{document.removeEventListener('pointermove',move);document.removeEventListener('pointerup',finish);document.removeEventListener('pointercancel',cancel);marker?.remove();render();};document.addEventListener('pointermove',move);document.addEventListener('pointerup',finish,{once:true});document.addEventListener('pointercancel',cancel,{once:true});});}
async function choosePhotos(){const input=document.createElement('input');input.type='file';input.accept='image/jpeg,image/png,image/webp';input.multiple=true;input.onchange=async()=>{for(const file of input.files){try{if(file.size>15*1024*1024)throw Error('15MB 이하 사진을 선택해주세요.');const bitmap=await createImageBitmap(file);const scale=Math.min(1,1600/Math.max(bitmap.width,bitmap.height)),canvas=document.createElement('canvas');canvas.width=Math.round(bitmap.width*scale);canvas.height=Math.round(bitmap.height*scale);canvas.getContext('2d').drawImage(bitmap,0,0,canvas.width,canvas.height);bitmap.close();const src=canvas.toDataURL('image/jpeg',.8);act(()=>M.day(state,ui.date).journal.push({id:M.id(),type:'photo',src}));}catch(e){toast('사진을 넣을 수 없습니다. '+e.message);}}};input.click();}
function importBackup(){const input=document.createElement('input');input.type='file';input.accept='.json,application/json';input.onchange=async()=>{try{if(input.files[0].size>100*1024*1024)throw Error('백업 파일이 너무 큽니다.');const imported=M.validateState(JSON.parse(await input.files[0].text()));openModal('백업 복원 확인',`<p>할 일 ${imported.tasks.length}개, 날짜 ${Object.keys(imported.days).length}개의 기록을 복원합니다.</p><p class="caption">현재 기록을 먼저 백업할 수 있습니다.</p><div class="actions">${btn('현재 기록 백업','export')}${btn('취소','close-modal')}<button class="primary" id="confirm-import">복원</button></div>`);$('#confirm-import').onclick=()=>{state=structuredClone(imported);state._rev=persistedRevision;ui.selected=null;render();persist();closeModal();toast('백업 기록을 불러왔습니다.');};}catch(e){toast('복원할 수 없습니다. '+e.message);}};input.click();}
document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='hidden'){clearTimeout(journalTimer);persist();}});
window.addEventListener('error',()=>toast('화면 처리 중 문제가 생겼습니다. 기록을 백업하고 새로고침해주세요.'));
async function init(){try{db=await openDB();const saved=await readState();if(saved){state=M.validateState(saved);persistedRevision=saved._rev||0;}render();if(!saved){openModal('나의 하루를 시작해보세요',`<p>먼저 + 할 일로 생각난 일을 적거나, / 키로 오늘 할 일을 추가해보세요.</p><p class="caption">Inbox에서 날짜와 카테고리를 정하고, 할 일을 PLAN 시간표로 끌어 계획할 수 있습니다.<br><br>기록은 이 브라우저에 저장됩니다. 일주일 사용 후 백업 파일을 내려받아 두세요.</p><div class="actions">${btn('시작하기','close-modal','','primary')}</div>`);await persist();}}catch(e){$('#app').innerHTML=`<div class="loading stack"><h2>저장소를 열 수 없습니다.</h2><p>브라우저의 사이트 저장 기능을 허용한 뒤 새로고침해주세요.</p><p class="caption">기존 기록은 덮어쓰지 않았습니다.</p></div>`;}}
init();
